# area: inheritance_mro
# hypothesis: A subclass that overrides a settable property with a getter-only property, or with a str-returning getter, is an error for mypy and ty but CPython runs it and raises AttributeError on assignment.
from typing import reveal_type


class Counter:
    def __init__(self) -> None:
        self._n = 0

    @property
    def count(self) -> int:
        return self._n

    @count.setter
    def count(self, value: int) -> None:
        self._n = value


class ReadOnlyCounter(Counter):
    @property
    def count(self) -> int:
        return self._n * 2


class Labeled(Counter):
    @property
    def count(self) -> str:  # expect-error
        return 'big'


def bump(c: Counter) -> None:
    c.count = 3


bump(Counter())
rc = ReadOnlyCounter()
print(rc.count)
reveal_type(rc.count)
try:
    rc.count = 4  # expect-error
except AttributeError:
    print('read-only property')
print(Labeled().count)
